import Delta from 'quill-delta';
import { EmbedBlot, Scope } from 'parchment';
import Quill from '../core/quill.js';
import logger from '../core/logger.js';
import Module from '../core/module.js';
import type { Range } from '../core/selection.js';
import Picker from '../ui/picker.js';

const debug = logger('quill:toolbar');

type Handler = (this: Toolbar, value: any) => void;

class SharedToolbar {
  controls: [string, HTMLElement][] = [];
  toolbars = new Set<Toolbar>();
  active: Toolbar | null = null;
  private attached = new WeakSet<HTMLElement>();
  private observer: MutationObserver;

  constructor(readonly container: HTMLElement) {
    this.observer = new MutationObserver(() => {
      this.container
        .querySelectorAll<HTMLElement>('button, select')
        .forEach((input) => this.attach(input));
      if (this.active != null && !this.isLive(this.active)) {
        this.active = null;
      }
      this.update();
    });
    this.observer.observe(document.body, { childList: true, subtree: true });
  }

  isLive(toolbar: Toolbar) {
    return document.body.contains(toolbar.quill.container);
  }

  add(toolbar: Toolbar) {
    this.toolbars.add(toolbar);
  }

  activate(toolbar: Toolbar) {
    if (!this.isLive(toolbar)) return;
    this.active = toolbar;
    this.update();
  }

  attach(input: HTMLElement) {
    if (this.attached.has(input)) return;
    const format = getFormat(input);
    if (format == null) return;
    this.attached.add(input);
    if (input.tagName === 'BUTTON') input.setAttribute('type', 'button');
    const eventName = input.tagName === 'SELECT' ? 'change' : 'click';
    input.addEventListener(eventName, (event) => {
      const toolbar = this.active;
      if (toolbar == null || !this.isLive(toolbar) || !toolbar.quill.isEnabled()) {
        event.preventDefault();
        return;
      }
      toolbar.handle(input, format, event);
    });
    this.controls.push([format, input]);
  }

  update() {
    const toolbar = this.active;
    const disabled = toolbar == null || !this.isLive(toolbar) || !toolbar.quill.isEnabled();
    this.controls.forEach(([, input]) => {
      // @ts-expect-error HTMLElement is a button or select here
      input.disabled = disabled;
      Picker.get(input as HTMLSelectElement)?.setDisabled(disabled);
